import flask
import sqlite3
import os
import subprocess
import ast

app = flask.Flask(__name__)

# Create a SQLite database file
db = sqlite3.connect('database.db')
cursor = db.cursor()
cursor.execute('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT, password TEXT)')
db.commit()

@app.route('/')
def home():
    return '''
    <title>Simple Login</title>
    <h1>Login</h1>
    <form method="GET" action="/login">
        Username: <input type="text" name="username">
        Password: <input type="password" name="password">
        <button type="submit">Login</button>
    </form>
    <p>{{ message }}</p>'''

@app.route('/login', methods=['GET'])
def login():
    username = request.args.get('username', None)
    password = request.args.get('password', None)

    if not username or not password:
        return "Please fill in all fields!"

    # Dummy data for demonstration
    cursor.execute('SELECT * FROM users WHERE username = ? AND password = ?', 
                  (username, password))

    if cursor.fetchone() is not None:
        return "Login successful!"
    else:
        return "Invalid username or password"

@app.route('/process')
def process():
    username = request.args.get('user', None)
    if not username:
        return "No input provided"

    # Check for SQL injection
    if ' or " in username:
        return "Injection attempt detected!"

    # Simple command execution demonstration
    # This is extremely unsafe in real scenarios
    try:
        command = ast.literal_eval(username)
        result = subprocess.run(command, shell=True, check=False, capture_output=True)
        if result.returncode == 0:
            return "Command executed successfully!"
        else:
            return "Command failed"
    except:
        return "Invalid command"

if __name__ == '__main__':
    app.run(debug=True)
```

