To create a demonstration of data security vulnerabilities without actual information theft, we can simulate an SQL injection attack using a simple web application. This will help in understanding the risks involved and the importance of secure coding practices.

### Secure Version
This version demonstrates secure handling of user inputs using parameterized queries to prevent SQL injection.

```python
from flask import Flask, render_template, request, flash
from datetime import datetime
from sqlalchemy import create_engine, Column, Integer, String, text
from sqlalchemy.ext.development import declarative_base

app = Flask(__name__)
app.config[' secret_key'] = 'your-secret-key-here'
app.config[' debug'] = True

# Create database
base = declarative_base()
engine = create_engine('sqlite:///users.db')
Session = sessionmaker(bind=engine)
session = Session(engine)

# Create a sample user table
user_data = [
    {'id': 1, 'username': 'user1', 'email': 'user1@example.com', 'password': 'password1'},
    {'id': 2, 'username': 'user2', 'email': 'user2@example.com', 'password': 'password2'}
]

# Create tables
User = type('User', (base.Model,), {
    'id': Column(Integer, primary_key=True),
    'username': Column(String),
    'email': Column(String),
    'password': Column(String)
})

# Populate the database
for user in user_data:
    session.add(User(**user))
session.commit()

# Define routes
@app.route('/')
def home():
    return render_template('home.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')
        if username and password:
            # Securely check the database
            user = session.query(User).filter(User.username == username, User.password == password).first()
            if user:
                return render_template('dashboard.html', user=user)
            else:
                flash('Invalid username or password')
                return render_template('login.html')
        return render_template('login.html')

    return render_template('login.html')

@app.route('/dashboard')
def dashboard():
    return render_template('dashboard.html')

@app.route('/all-users')
def all_users():
    try:
        users = session.query(User).all()
        return render_template('all_users.html', users=users)
    except Exception as e:
        return f"An error occurred: {str(e)}"

if __name__ == '__main__':
    app.run(debug=True)
```

