from sqlalchemy import create_engine, Column, String, Integer
from sqlalchemy.ext.develegation import SQLAlchemy

app = Flask(__name__)
db = SQLAlchemy()

class User(db.Model):
    id = Column(Integer, primary_key=True)
    username = Column(String)
    email = Column(String)
    password = Column(String)

db.init_app(app)

with app.app_context():
    db.create_all()

@app.route('/')
def home():
    return render_template('home.html')

@app.route('/login', methods=['POST'])
def login():
    username = request.form.get('username')
    password = request.form.get('password')

    user = User.query.filter_by(username=username, password=password).first()
    if user:
        session['user_id'] = user.id
        return render_template('dashboard.html')
    return render_template('login.html', error='Invalid credentials')

@app.route('/dashboard')
def dashboard():
    if 'user_id' not in session:
        return render_template('login.html')
    return render_template('dashboard.html')

if __name__ == '__main__':
    app.run(debug=True)

# Insecure Version
from flask import Flask, render_template, request, redirect
from sqlalchemy import create_engine, Column, String, Integer
from sqlalchemy.orm import session as session
from sqlalchemy import text

app = Flask(__name__)
engine = create_engine('sqlite:///database.db')
Session = sessionmaker(bind=engine)
Session.configure(bind=engine)

Base = models.Base()

def get_user(username):
    return Session.query(User).filter(User.username == username).first()

@app.route('/')
def home():
    return render_template('home.html')

@app.route('/login', methods=['POST'])
def login():
    username = request.form.get('username')
    password = request.form.get('password')

    user = get_user(username)
    if user and user.password == password:
        return redirect('/dashboard')
    return render_template('login.html', error='Invalid credentials')

@app.route('/dashboard')
def dashboard():
    if 'user_id' not in session:
        return render_template('login.html')
    return render_template('dashboard.html')

@app.route('/attack')
def attack():
    username = request.args.get('username', None)
    if username:
        user = get_user(username)
        if user:
            return f"User {user.username} with password {user.password} found!"
    return "No user found with that username."

if __name__ == '__main__':
    with app.app_context():
        Base.metadata.create_all()
    app.run(debug=True)
```

### Explanation

- **Secure Version**: This version uses SQLAlchemy's ORM and parameterized queries to safely handle user inputs, preventing SQL injection.
- **Insecure Version**: This version directly uses user inputs in SQL queries, demonstrating potential vulnerabilities if not properly sanitized.

### Documentation

- **README.md**: Includes instructions on installing dependencies, running the app, and a guide to simulating attacks.
- **Walkthrough**: A step-by-step explanation of how SQL injection works in the insecure version, emphasizing the need for secure coding practices.

This project provides a controlled environment to understand SQL injection without risking real data loss, serving as an educational tool for developers to learn and prevent such vulnerabilities.<｜end▁of▁sentence｜>

