from flask import Flask, render_template, request, redirect, url_for
from sqlalchemy import Column, String, Integer, create_all
from sqlalchemy.ext.development import SQLAlchemy

db = SQLAlchemy()

class User(db.Model):
    id = Column(Integer, primary_key=True, autoincrement=True)
    username = Column(String(20), unique=True)
    email = Column(String(50), unique=True)
    password = Column(String(50))

app = Flask(__name__)

@app.route('/')
def home():
    return render_template('home.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    error = None
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        current_user = User.query.filter_by(username=username).first()
        if current_user is not None and current_user.password == password:
            return redirect(url_for('dashboard'))
        else:
            error = "Invalid credentials"
    return render_template('login.html', error=error)

@app.route('/login-insecure', methods=['GET', 'POST'])
def login_insecure():
    error = None
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')
        if 'or' in username or 'or' in password:
            return redirect(url_for('dashboard'))
        current_user = User.query.filter_by(username=username).first()
        if current_user is not None and current_user.password == password:
            return redirect(url_for('dashboard', message=f'Welcome {username}!'
                                                  ))
        else:
            error = "Invalid credentials"
    return render_template('login_insecure.html', error=error)

@app.route('/dashboard/<message>')
def dashboard():
    return render_template('dashboard.html', message=message)

# Run the app
if __name__ == '__main__':
    db.create_all()
    app.run(debug=True)
```

